class UI(_d.Page):
    BACKGROUND = 0xC408  # #0b1a22
    DEFAULTS = DEFAULTS
    # (id, x, y, w, h, parameters) in layer order: the first one is the lowest.
    WIDGETS = (
        ("title", 10, 4, 200, 24, ()),
        ("bat", 230, 4, 83, 24, ("battery",)),
        ("dial", 10, 36, 141, 141, ()),
        ("scale", 20, 56, 121, 66, ("temperature",)),
        ("needle", 80, 120, 52, 2, ("temperature",)),
        ("hub", 69, 109, 23, 23, ()),
        ("t_val", 20, 134, 123, 36, ("temperature",)),
        ("h_bar", 164, 36, 148, 36, ("humidity",)),
        ("co2_lbl", 164, 82, 60, 24, ()),
        ("co2_val", 226, 78, 88, 30, ("co2",)),
        ("co2_warn", 164, 112, 148, 20, ("co2",)),
        ("trend", 10, 182, 302, 54, ("history",)),
    )

    def set_temperature(self, value):
        self.p["temperature"] = value
        return self.update()

    def set_humidity(self, value):
        self.p["humidity"] = value
        return self.update()

    def set_co2(self, value):
        self.p["co2"] = value
        return self.update()

    def set_battery(self, value):
        self.p["battery"] = value
        return self.update()

    def set_history(self, value):
        self.p["history"] = value
        return self.update()

    def _draw_title(self, fb, ox, oy):
        _d.label(fb, "Датчики", 10 - ox, 4 - oy, 200, 24, 0x199F, _f.SERIF_16, _d.LEFT)

    def _draw_bat(self, fb, ox, oy):
        # redrawn when changed: battery
        p = self.p
        color = 0x158D
        # conditions, top to bottom: the lowest one that matches wins
        if p["battery"] < 20:
            color = 0x4AFA
        _d.label(
            fb,
            _d.fmt("%d%%", p["battery"]),
            230 - ox,
            4 - oy,
            82,
            24,
            color,
            _f.SERIF_14,
            _d.RIGHT,
        )

    def _draw_dial(self, fb, ox, oy):
        _d.ellipse(fb, 10 - ox, 36 - oy, 141, 141, 0x0511)

    def _draw_scale(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        _d.arc(
            fb,
            20 - ox,
            56 - oy,
            121,
            66,
            _d.frac(p["temperature"], -20.0, 50.0),
            0x1F4D,
            _d.num(p["temperature"], True),
            _f.SERIF_8,
        )

    def _draw_needle(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        angle = 0.0
        angle = _d.lin(p["temperature"], -20.0, 50.0, -180.0, 0.0)
        r = _d.rot(angle, 80 - ox, 120 - oy)
        _d.line(fb, 80 - ox, 120 - oy, 50, 0, 0x4AFA, r)

    def _box_needle(self):
        p = self.p
        angle = 0.0
        angle = _d.lin(p["temperature"], -20.0, 50.0, -180.0, 0.0)
        return _d.rbox(80, 120, 52, 2, angle, 80, 120)

    def _draw_hub(self, fb, ox, oy):
        _d.ellipse(fb, 69 - ox, 109 - oy, 23, 23, 0xFFFF)

    def _draw_t_val(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        _d.label(
            fb,
            _d.fmt("%.1f°C", p["temperature"]),
            20 - ox,
            134 - oy,
            121,
            36,
            0xFFFF,
            _f.SERIF_24,
            _d.CENTER,
        )

    def _draw_h_bar(self, fb, ox, oy):
        # redrawn when changed: humidity
        p = self.p
        _d.bar(
            fb,
            164 - ox,
            36 - oy,
            148,
            36,
            _d.frac(p["humidity"], 0, 100),
            0x545E,
            "Вологість, %",
            _d.num(p["humidity"], False),
            _f.SERIF_12,
        )

    def _draw_co2_lbl(self, fb, ox, oy):
        _d.label(fb, "CO₂, ppm", 164 - ox, 82 - oy, 60, 24, 0x158D, _f.SERIF_12, _d.LEFT)

    def _draw_co2_val(self, fb, ox, oy):
        # redrawn when changed: co2
        p = self.p
        color = 0x545E
        # conditions, top to bottom: the lowest one that matches wins
        if p["co2"] > 1000:
            color = 0x24ED
        if p["co2"] > 1500:
            color = 0x4AFA
        _d.label(
            fb,
            _d.fmt("%d", p["co2"]),
            226 - ox,
            78 - oy,
            86,
            30,
            color,
            _f.SERIF_24,
            _d.RIGHT,
        )

    def _draw_co2_warn(self, fb, ox, oy):
        # redrawn when changed: co2
        p = self.p
        visible = True
        # conditions, top to bottom: the lowest one that matches wins
        if p["co2"] <= 1000:
            visible = False
        if not visible:
            return
        _d.label(
            fb,
            "Провітріть приміщення",
            164 - ox,
            112 - oy,
            148,
            20,
            0x4AFA,
            _f.SERIF_12,
            _d.LEFT,
        )

    def _draw_trend(self, fb, ox, oy):
        # redrawn when changed: history
        p = self.p
        _d.chart(
            fb,
            10 - ox,
            182 - oy,
            302,
            54,
            p["history"],
            True,
            10.0,
            30.0,
            None,
            None,
            "",
            "°C",
            "line",
            True,
            0x24ED,
            _f.SERIF_8,
        )
